// Phase: selection UI.
// Vanilla JS, no build step. Fetches the corpus index (SELECT_CONFIG.INDEX_URL, generated by
// scripts/build_corpus_index.py), plays clips from SELECT_CONFIG.AUDIO_BASE_URL + filename,
// lets the curator filter, pick and categorise entries, and exports candidates.json (the
// input of the ASR phase). Picks persist in localStorage and can be re-loaded from a
// previously saved candidates.json. Served over http (scripts/dev_server.py locally).

(function () {
  const CONFIG = window.SELECT_CONFIG;
  let ALL_ENTRIES = [];
  const PAGE_SIZE = 100;
  const CATEGORIES = ["greetings", "directions", "lodging", "food", "transactions"];
  const STORAGE_KEY = "task3.selection.v1";

  const selected = new Map(); // id -> entry (with chosen category)
  let visibleCount = PAGE_SIZE;

  const $ = (id) => document.getElementById(id);
  const searchInput = $("search");
  const validationFilter = $("validationFilter");
  const categoryFilter = $("categoryFilter");
  const selectedOnly = $("selectedOnly");
  const counts = $("counts");
  const corpusBody = $("corpusBody");
  const loadMoreBtn = $("loadMoreBtn");
  const loadMoreWrap = $("loadMoreWrap");
  const selectedList = $("selectedList");
  const selectedCount = $("selectedCount");
  const exportBtn = $("exportBtn");
  const exportHint = $("exportHint");

  function option(value, label) {
    const o = document.createElement("option");
    o.value = value;
    o.textContent = label;
    return o;
  }

  // Category filter applies to categories assigned so far (selected entries only).
  categoryFilter.append(option("", "All categories"), option("__none__", "Unassigned"));
  for (const c of CATEGORIES) categoryFilter.append(option(c, c));

  function categoryOf(entry) {
    const s = selected.get(entry.id);
    return s ? s.category : null;
  }

  function filteredEntries() {
    const q = searchInput.value.trim().toLowerCase();
    const val = validationFilter.value;
    const cat = categoryFilter.value;
    return ALL_ENTRIES.filter((e) => {
      if (val === "validated" && e.status !== "validated") return false;
      if (val === "not_validated" && e.status === "validated") return false;
      if (selectedOnly.checked && !selected.has(e.id)) return false;
      if (cat === "__none__" && categoryOf(e)) return false;
      if (cat && cat !== "__none__" && categoryOf(e) !== cat) return false;
      if (q && !(e.reference_text + " " + e.prompt).toLowerCase().includes(q)) return false;
      return true;
    });
  }

  function renderBrowse() {
    const entries = filteredEntries();
    counts.textContent = `${entries.length.toLocaleString()} of ${ALL_ENTRIES.length.toLocaleString()} entries match`;

    corpusBody.innerHTML = "";
    for (const entry of entries.slice(0, visibleCount)) {
      const tr = document.createElement("tr");

      const tdPick = document.createElement("td");
      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.checked = selected.has(entry.id);
      cb.addEventListener("change", () => {
        toggleSelect(entry, cb.checked);
        sel.disabled = !cb.checked;
        if (!cb.checked) sel.value = "";
      });
      tdPick.appendChild(cb);

      const tdAudio = document.createElement("td");
      const audio = document.createElement("audio");
      audio.controls = true;
      audio.preload = "none";
      audio.src = CONFIG.AUDIO_BASE_URL + encodeURIComponent(entry.audio_filename);
      tdAudio.appendChild(audio);

      const tdText = document.createElement("td");
      tdText.textContent = entry.reference_text || "(no transcription)";
      if (entry.prompt) {
        const p = document.createElement("span");
        p.className = "prompt";
        p.textContent = "Q: " + entry.prompt;
        tdText.appendChild(p);
      }

      const tdSource = document.createElement("td");
      tdSource.className = "source";
      tdSource.textContent = `${entry.status.replace("_", " ")} · ${(entry.duration_ms / 1000).toFixed(1)}s`;

      const tdCat = document.createElement("td");
      const sel = document.createElement("select");
      sel.append(option("", "— assign —"));
      for (const c of CATEGORIES) sel.append(option(c, c));
      sel.value = categoryOf(entry) || "";
      sel.disabled = !selected.has(entry.id);
      sel.addEventListener("change", () => {
        const s = selected.get(entry.id);
        if (s) {
          s.category = sel.value || null;
          renderSelected();
        }
      });
      tdCat.appendChild(sel);

      tr.append(tdPick, tdAudio, tdText, tdSource, tdCat);
      corpusBody.appendChild(tr);
    }

    loadMoreWrap.style.display = entries.length > visibleCount ? "" : "none";
  }

  function toggleSelect(entry, isChecked) {
    if (isChecked) selected.set(entry.id, { ...entry, category: null });
    else selected.delete(entry.id);
    renderSelected();
  }

  function renderSelected() {
    selectedList.innerHTML = "";
    const tally = new Map();
    for (const entry of selected.values()) {
      const li = document.createElement("li");
      const catLabel = entry.category || "(no category yet)";
      li.textContent = `${entry.reference_text || entry.audio_filename} — ${catLabel}`;
      selectedList.appendChild(li);
      tally.set(catLabel, (tally.get(catLabel) || 0) + 1);
    }
    selectedCount.textContent = String(selected.size);
    persist();
    $("categoryTally").textContent = Array.from(tally.entries())
      .map(([cat, n]) => `${cat}: ${n}`)
      .join("  ·  ");

    const uncategorised = Array.from(selected.values()).filter((e) => !e.category).length;
    exportBtn.disabled = selected.size === 0 || uncategorised > 0;
    exportHint.textContent = uncategorised
      ? `${uncategorised} selected entr${uncategorised === 1 ? "y has" : "ies have"} no category yet; assign one to enable export.`
      : "";
  }

  function candidatesJson() {
    const candidates = Array.from(selected.values()).map((e) => ({
      id: e.id,
      audio_filename: e.audio_filename,
      reference_text: e.reference_text,
      status: e.status,
      category: e.category,
    }));
    return JSON.stringify(candidates, null, 2) + "\n";
  }

  async function exportCandidates() {
    const text = candidatesJson();
    // Chrome can save to a chosen folder (e.g. task3/data/selected/); others download.
    if (window.showSaveFilePicker) {
      try {
        const handle = await window.showSaveFilePicker({
          suggestedName: "candidates.json",
          types: [{ description: "JSON", accept: { "application/json": [".json"] } }],
        });
        const w = await handle.createWritable();
        await w.write(text);
        await w.close();
        return;
      } catch (err) {
        if (err.name === "AbortError") return;
      }
    }
    const url = URL.createObjectURL(new Blob([text], { type: "application/json" }));
    const a = document.createElement("a");
    a.href = url;
    a.download = "candidates.json";
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  }

  function resetAndRender() {
    visibleCount = PAGE_SIZE;
    renderBrowse();
  }
  searchInput.addEventListener("input", resetAndRender);
  validationFilter.addEventListener("change", resetAndRender);
  categoryFilter.addEventListener("change", resetAndRender);
  selectedOnly.addEventListener("change", resetAndRender);
  loadMoreBtn.addEventListener("click", () => {
    visibleCount += PAGE_SIZE;
    renderBrowse();
  });
  exportBtn.addEventListener("click", exportCandidates);

  const importBtn = $("importBtn");
  const importFile = $("importFile");
  importBtn.addEventListener("click", () => importFile.click());
  importFile.addEventListener("change", async () => {
    const file = importFile.files[0];
    importFile.value = "";
    if (!file) return;
    try {
      const rows = JSON.parse(await file.text());
      if (!Array.isArray(rows)) throw new Error("expected a JSON array");
      restore(rows);
      resetAndRender();
    } catch (err) {
      showError(`Could not load that file: ${err.message}`);
    }
  });

  function showError(message) {
    const el = $("loadError");
    el.textContent = message;
    el.hidden = false;
  }

  function persist() {
    if (ALL_ENTRIES.length === 0) return; // index failed to load: keep the saved picks
    try {
      const picks = Array.from(selected.values(), (e) => ({ id: e.id, category: e.category }));
      localStorage.setItem(STORAGE_KEY, JSON.stringify(picks));
    } catch (_) { /* storage unavailable: picks just won't persist */ }
  }

  // rows: [{id, category}, ...]; ids missing from the current index are skipped.
  function restore(rows) {
    const byId = new Map(ALL_ENTRIES.map((e) => [e.id, e]));
    selected.clear();
    for (const r of rows) {
      const entry = byId.get(r && r.id);
      if (!entry) continue;
      selected.set(entry.id, { ...entry, category: CATEGORIES.includes(r.category) ? r.category : null });
    }
    renderSelected();
  }

  async function init() {
    try {
      const res = await fetch(CONFIG.INDEX_URL);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      ALL_ENTRIES = await res.json();
    } catch (err) {
      showError(
        `Could not load the corpus index (${err.message}). Run python3 scripts/build_corpus_index.py ` +
        "and open this page through python3 scripts/dev_server.py."
      );
    }
    try {
      if (ALL_ENTRIES.length) restore(JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]"));
    } catch (_) { /* ignore a corrupt or unavailable saved selection */ }
    renderBrowse();
    renderSelected();
  }

  init();
})();
